"""Build the project report PDF from generated run artifacts."""
from pathlib import Path
import csv, json
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Preformatted

ROOT=Path(__file__).resolve().parents[1]
def read_csv(p):
    with p.open(encoding="utf-8",newline="") as f: return list(csv.DictReader(f))
def footer(canvas,doc):
    canvas.saveState(); canvas.setFont("Helvetica",8); canvas.setFillColor(colors.HexColor("#617184"))
    canvas.drawString(.65*inch,.4*inch,"Railway Feeder Connection Risk | Synthetic MLOps demonstration")
    canvas.drawRightString(7.85*inch,.4*inch,f"Page {doc.page}"); canvas.restoreState()
def build():
    metrics=json.loads((ROOT/"reports"/"metrics.json").read_text(encoding="utf-8"))
    v1=read_csv(ROOT/"data/raw/transfers_v1.csv"); v2=read_csv(ROOT/"data/raw/transfers_v2.csv")
    styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name="CoverTitle",parent=styles["Title"],fontSize=25,leading=30,textColor=colors.HexColor("#12304A"),alignment=TA_CENTER,spaceAfter=12))
    styles.add(ParagraphStyle(name="Deck",parent=styles["Normal"],fontSize=12,leading=18,textColor=colors.HexColor("#45586B"),alignment=TA_CENTER))
    styles["Heading1"].textColor=colors.HexColor("#12304A"); styles["Heading2"].textColor=colors.HexColor("#147D80")
    story=[]
    story += [Spacer(1,1.1*inch),Paragraph("Predicting Missed Connections",styles["CoverTitle"]),Paragraph("Between Railway Trains and Feeder Buses",styles["CoverTitle"]),Spacer(1,.15*inch),Paragraph("End-to-end synthetic MLOps project report",styles["Deck"]),Spacer(1,.8*inch)]
    story += [Paragraph("Project objective",styles["Heading2"]),Paragraph("Estimate whether passengers arriving on an inbound train are at risk of missing their scheduled feeder bus. The system combines anticipated train delay, walking distance and speed, crowd density, luggage, transfer allowance, and vertical-access availability.",styles["BodyText"]),Spacer(1,.3*inch)]
    champion=metrics["selected_model"]
    story += [Paragraph("At a glance",styles["Heading2"]),Table([["Synthetic records","Models compared","Selected model","Registry name"],["600 (300 per version)","Decision Tree; Gradient Boosting",champion,"FeederConnectionRisk"]],colWidths=[1.45*inch,2.0*inch,1.6*inch,1.65*inch],style=TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#12304A")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("BACKGROUND",(0,1),(-1,-1),colors.HexColor("#EAF2F5")),("GRID",(0,0),(-1,-1),.5,colors.white),("VALIGN",(0,0),(-1,-1),"MIDDLE"),("FONTSIZE",(0,0),(-1,-1),8),("TOPPADDING",(0,0),(-1,-1),9),("BOTTOMPADDING",(0,0),(-1,-1),9)]))]
    story += [PageBreak(),Paragraph("1. Problem analysis",styles["Heading1"]),Paragraph("A connection is vulnerable when operational delay and the time needed to cross the station consume most or all of the scheduled transfer window. Distance alone is insufficient: crowding, slow walking, luggage, and inaccessible vertical routes increase time to reach the boarding point. The output is a passenger-facing binary message with a missed-connection probability for downstream decisions.",styles["BodyText"]),Paragraph("Synthetic data and version management",styles["Heading2"]),Paragraph(f"Version 1 contains {len(v1)} baseline records with moderate delay and crowd distributions. Version 2 contains {len(v2)} peak-hour records generated with higher mean delay and denser crowds. Data generation is deterministic using fixed seeds; the source CSVs and engineered feature-store snapshots are committed with this project.",styles["BodyText"])]
    counts=[["Version","Records","Missed: Yes","Missed rate"]]
    for nm,rows in [("V1",v1),("V2 peak hour",v2)]:
        yes=sum(r["missed_connection"]=="Yes" for r in rows); counts.append([nm,str(len(rows)),str(yes),f"{yes/len(rows):.1%}"])
    story += [Spacer(1,8),Table(counts,colWidths=[2.0*inch,1.25*inch,1.5*inch,1.5*inch],style=TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#147D80")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("GRID",(0,0),(-1,-1),.5,colors.HexColor("#CBD5DF")),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F1F6F8")]),("PADDING",(0,0),(-1,-1),7)])),Spacer(1,8),Paragraph("Target labels are sampled from a rule based on the transfer margin with a stochastic buffer to represent unobserved queueing and boarding variability. This means the benchmark is deliberately learnable and is not evidence of real-world quality.",styles["BodyText"])]
    story += [Paragraph("2. System architecture",styles["Heading1"]),Preformatted("Synthetic generator (V1 + peak-hour V2)\n           |\nShared feature pipeline -> CSV feature repository\n           |\nTrain / stratified holdout -> Decision Tree + Gradient Boosting\n           |\nRecall-first selection -> MLflow experiment + registered model\n           |\nWeb dashboard + FastAPI -> Connection Likely | Connection at Risk",ParagraphStyle("arch",parent=styles["Code"],fontName="Courier",fontSize=9,leading=14,backColor=colors.HexColor("#F0F5F7"),borderPadding=10)),Paragraph("The API and training share the same feature engineering function to prevent training-serving skew. The local MLflow tracking and registry store uses the repository's filesystem. The browser dashboard summarizes data versions, model quality and registry status, and can start model retraining. A joblib copy of the selected pipeline supports a simple local service startup.",styles["BodyText"])]
    story += [PageBreak(),Paragraph("3. Feature engineering",styles["Heading1"]),Paragraph("Walking time accounts for distance, passenger pace, crowd density, luggage burden, and lift/escalator availability. Crowd density is bounded from 0 to 1. Luggage penalties represent added difficulty, and a fixed access penalty is applied if vertical access is unavailable.",styles["BodyText"]),Preformatted("base_walk_min = distance_m / speed_mps / 60\nestimated_walking_time_min = base_walk_min * (1 + 0.8*crowd + luggage_penalty)\n                           + 0.75 if lift/escalator unavailable\ntransfer_time_margin_min = scheduled_transfer_time_min\n                            - expected_train_delay_min\n                            - estimated_walking_time_min",styles["Code"]),Paragraph("The reusable feature repository writes one engineered CSV snapshot per dataset version. Inference computes these same features per request. Margin below zero indicates the estimated walk would finish after bus departure.",styles["BodyText"]),Paragraph("4. Training and model evaluation",styles["Heading1"]),Paragraph("Both classifiers use the same stratified 75/25 holdout from pooled V1 and V2 records. Numeric features are imputed and scaled; categorical variables are imputed and one-hot encoded. Selection prioritizes recall for the missed class, with F1 as a tie-breaker, because missed passengers are the primary failure mode under study.",styles["BodyText"])]
    comparison=[["Classifier","Accuracy","Precision (missed)","Recall (missed)","F1 (missed)","ROC AUC"]]
    for name in ["decision_tree","gradient_boosting"]:
        m=metrics[name]["metrics"]; comparison.append([name.replace("_"," "),*[f"{m[k]:.3f}" for k in ["accuracy","precision_missed","recall_missed","f1_missed","roc_auc"]]])
    story += [Spacer(1,8),Table(comparison,colWidths=[1.45*inch,.85*inch,1.15*inch,1.1*inch,.9*inch,.75*inch],style=TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#12304A")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("FONTSIZE",(0,0),(-1,-1),8),("GRID",(0,0),(-1,-1),.5,colors.HexColor("#CBD5DF")),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F1F6F8")]),("PADDING",(0,0),(-1,-1),6)])),Spacer(1,8)]
    for name in ["decision_tree","gradient_boosting"]:
        story.append(Paragraph(f"{name.replace('_',' ').title()} confusion matrix (true rows [No, Yes], predicted columns [No, Yes]): {metrics[name]['metrics']['confusion_matrix']}",styles["BodyText"]))
    story += [Spacer(1,8),Paragraph("These metrics describe only a synthetic random holdout. Production validation should use time-based splits, independent stations, probability calibration, subgroup error checks, and live operational outcomes.",styles["BodyText"]),PageBreak(),Paragraph("5. Model registry and release",styles["Heading1"]),Paragraph(f"MLflow experiment: railway-feeder-connection-risk. Both training runs log model artifacts, parameters, metrics, and confusion matrices. The selected model is registered as version 1 under FeederConnectionRisk; the champion is {champion}. The local artifacts are reproducible with python -m src.train.",styles["BodyText"]),Paragraph("6. CI/CD and serving",styles["Heading1"]),Paragraph("GitHub Actions runs on pushes and pull requests. Its validation job installs dependencies, regenerates both data versions, trains and registers a model, and runs tests for the walking-time calculation, congestion/access effects, API prediction and dashboard summary. All 4 project tests passed locally. The hosted GitHub Actions workflow will run after the repository is pushed.",styles["BodyText"]),Paragraph("The web dashboard is served at `/` and presents data versions, model metrics, registry status, a retraining action and a live prediction form. FastAPI also offers GET /health, POST /predict, and `/docs`. For examples/request.json, the selected model returns Connection Likely with missed-connection probability 0.0000, estimated walk 2.1167 minutes, and margin 9.8833 minutes. The recorded response is in examples/prediction.json.",styles["BodyText"]),Paragraph("7. Limitations and next steps",styles["Heading1"]),Paragraph("The synthetic label is derived from engineered transfer margin, so it partially encodes inputs by construction. There are no real passenger observations, service calendars, platform changes, boarding queues, or bus dispatch interventions. Before operational use, collect consent-aware, privacy-minimized outcomes; define service-specific thresholds; evaluate false negatives with transport operators; monitor drift and calibration; and document the human response to risk alerts.",styles["BodyText"]),Paragraph("Repository contents",styles["Heading2"]),Paragraph("src/ contains the generator, reusable features, trainer, and API; web/ contains the browser dashboard. data/raw/ contains versioned CSVs; data/feature_store/ contains engineered snapshots. tests/ and .github/workflows/ define validation. reports/ contains metrics, model card, and this report. examples/ contains the request and response payloads.",styles["BodyText"])]
    out=ROOT/"reports"/"railway_feeder_mlops_report.pdf"; out.parent.mkdir(exist_ok=True)
    SimpleDocTemplate(str(out),pagesize=letter,rightMargin=.65*inch,leftMargin=.65*inch,topMargin=.65*inch,bottomMargin=.7*inch,title="Railway Feeder Connection Risk MLOps Report",author="MLOps project").build(story,onFirstPage=footer,onLaterPages=footer)
    print(out)
if __name__=="__main__": build()
